CREATE OR REPLACE FUNCTION public.get_email_for_phone(phone text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  normalized text;
  result text;
begin
  normalized := trim(phone);
  if normalized is null or normalized = '' then
    return null;
  end if;
  if normalized !~ '^\+[1-9][0-9]{7,14}$' then
    return null;
  end if;

  select coalesce(users.email, profiles.email) into result
  from public.profiles profiles
  join auth.users users on users.id = profiles.id
  where profiles.phone = normalized
  order by profiles.id
  limit 1;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_phone_for_email(email text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  normalized text;
  result text;
begin
  normalized := lower(trim(email));
  if normalized is null or normalized = '' then
    return null;
  end if;

  select coalesce(users.phone, profiles.phone) into result
  from public.profiles profiles
  join auth.users users on users.id = profiles.id
  where lower(coalesce(users.email, profiles.email, '')) = normalized
  order by profiles.id
  limit 1;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_phone_available(phone text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  normalized text;
begin
  normalized := trim(phone);
  if normalized is null or normalized = '' then
    return false;
  end if;
  if normalized !~ '^\+[1-9][0-9]{7,14}$' then
    return false;
  end if;
  return not exists (
    select 1
    from public.profiles
    where profiles.phone = normalized
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.is_username_available(username text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if username is null or length(trim(username)) < 3 then
    return false;
  end if;
  return not exists (
    select 1
    from public.profiles
    where lower(display_name) = lower(trim(username))
  );
end;
$function$
